import{VicePresidentCard}from"./VicePresidentCard.js";export function Timeline(i){if(0===i.length)return'<div class="no-results">No Vice Presidents found matching your criteria.</div>';return`\n        <div class="timeline-container">\n            <div class="timeline-nav-wrapper">\n                <div class="timeline-track"></div>\n                <div class="timeline-nav">\n                    ${i.map(i=>`\n        <div class="timeline-nav-item" data-target="vp-${i.originalIndex}" title="${i.name} (${i.electionYear.substring(0,4)})">\n            <div class="timeline-dot"></div>\n            <div class="timeline-year-label">${i.electionYear.substring(0,4)}</div>\n        </div>\n    `).join("")}\n                </div>\n            </div>\n            <div class="cards-grid">\n                ${i.map(i=>`\n        <div class="card-wrapper">\n            ${VicePresidentCard(i,i.originalIndex)}\n        </div>\n    `).join("")}\n            </div>\n        </div>\n    `}